use verus::prelude::*;

// A pure specification function that maps a single ASCII character to its lowercase
// counterpart if it lies in 'A'..='Z', and otherwise returns it unchanged.
#[verifier(spec)]
fn ascii_to_lower(c: char) -> char {
    if 'A' <= c && c <= 'Z' {
        // ASCII difference between 'A' and 'a' is 32
        char::from_u32(c as u32 + 32).unwrap()
    } else {
        c
    }
}

/// Specification for to_lowercase: takes a &Vec<char> and returns
/// a new Vec<char> of the same length, where each character at index i
